Export.Routine:
ReadAndCreateList ;
if ( $DATA(^BBankCodesList) = 1 && $LISTVALID(^BBankCodesList) ) { WRITE !, "List already exists" RETURN } set ^BBankCodesList = $LISTBUILD("") Set InFile="/home/lpjnaras/MisysBBankCodes" ;name of infile – FILE.TXT Set OutFile="/home/lpjnaras/FILE2.TXT" ;name of outfile – FILE2.TXT Close InFile,OutFile ;close a file before you open it Open InFile:"R":10 ;open the file for reading, timeout 10 sec Write !, "Opened infile" If '$Test Write !,InFile," cannot be opened." Quit ;cannot open file Open OutFile:"WNS":10 ;open file for write, new, timeout of 10 sec If '$Test Write !,OutFile," cannot be opened." Quit ;cannot open file Set (InCount,OutCount)=0 ;init counter of records read and write Set X=$ZU(68,40,1) ;enables the $ZEOF special variable ;Set system.Process.SetZEOF(1) ;enable the $ZEOF special variable Set EOF=0 Do { ;EOF is the end of file switch Use InFile ;sets InFile as the current device Read InRecord ;read record from file
If $ZEOF=-1 Set EOF=1 Quit ;$ZEOF=-1 when end of file reached Set X=$Increment(InCount) ;increment counter Use 0 Write !,InRecord ;display record Set X=$Increment(OutCount) ;increment counter Set $LI(^BBankCodesList,InCount)=InRecord // Use OutFile ;sets OutFile as the current device // Write InRecord,! } While EOF=0 ;read until end of file Use 0 Write !,InCount," Records read" Use 0 Write !,OutCount," Records written" Use 0 Write !,"End of File reached" Quit
